type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue };
type JsonObject = { [key: string]: JsonValue };

function isPlainObject(value: JsonValue): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function mergeDeep(a: JsonValue, b: JsonValue): JsonValue {
  if (isPlainObject(a) && isPlainObject(b)) {
    const result: JsonObject = { ...a };
    for (const key of Object.keys(b)) {
      if (Object.prototype.hasOwnProperty.call(result, key)) {
        result[key] = mergeDeep(result[key], b[key]);
      } else {
        result[key] = b[key];
      }
    }
    return result;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    const result: JsonValue[] = [...a];
    const seen = new Set<string>(a.map((item) => JSON.stringify(item)));
    for (const item of b) {
      const key = JSON.stringify(item);
      if (!seen.has(key)) {
        result.push(item);
        seen.add(key);
      }
    }
    return result;
  }
  return b;
}

function sortJson(value: JsonValue): JsonValue {
  if (Array.isArray(value)) {
    return value.map(sortJson);
  }
  if (isPlainObject(value)) {
    const result: JsonObject = {};
    const keys = Object.keys(value).sort();
    for (const key of keys) {
      result[key] = sortJson(value[key]);
    }
    return result;
  }
  return value;
}

