  const str = Math.floor(value).toString();
  const parts: string[] = [];
  let count = 0;
  for (let i = str.length - 1; i >= 0; i--) {
    if (count > 0 && count % 3 === 0) parts.push(',');
    parts.push(str[i]);
    count++;
  }
  return parts.reverse().join('');
}

