void add_level(Level **levels, int *count, int *cap, const char *name, int add) {
    for (int i = 0; i < *count; i++) {
        if (strcmp((*levels)[i].name, name) == 0) {
            (*levels)[i].count += add;
            return;
        }
    }
    if (*count == *cap) {
        *cap = *cap ? *cap * 2 : 4;
        *levels = (Level *)realloc(*levels, *cap * sizeof(Level));
