        *components = (Component *)realloc(*components, *cap * sizeof(Component));
    }
    (*components)[*count].name = strdup(name);
    (*components)[*count].count = add;
    (*count)++;
}

void add_message(char ***messages, int *count, int *cap, const char *msg) {
    for (int i = 0; i < *count; i++) {
        if (strcmp((*messages)[i], msg) == 0) return;
    }
    if (*count == *cap) {
        *cap = *cap ? *cap * 2 : 4;
        *messages = (char **)realloc(*messages, *cap * sizeof(char *));
    }
    (*messages)[*count] = strdup(msg);
    (*count)++;
}

