struct FileEntry {
    rel: String,
    ext: String,
    lines: u64,
    chars: u64,
}

fn walk(dir: &Path, rel: &Path, files: &mut Vec<FileEntry>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let file_type = match entry.file_type() {
            Ok(ft) => ft,
            Err(_) => continue,
        };
        if file_type.is_symlink() {
            continue;
        }
        let path = entry.path();
        let name = entry.file_name();
        let child_rel = rel.join(&name);
        if file_type.is_dir() {
            walk(&path, &child_rel, files);
        } else if file_type.is_file() {
            let bytes = fs::read(&path).unwrap_or_default();
            let mut line_count: u64 = 0;
            for &b in &bytes {
                if b == b'\n' {
                    line_count += 1;
                }
            }
            if !bytes.is_empty() && bytes.last() != Some(&b'\n') {
                line_count += 1;
            }
            let chars = bytes.len() as u64;
            let ext = path.extension()
                .and_then(|e| e.to_str())
                .map(|e| format!(".{}", e))
                .unwrap_or_default();
            let rel_str = child_rel.display().to_string();
            files.push(FileEntry {
                rel: rel_str,
                ext,
                lines: line_count,
                chars,
            });
        }
    }
}

