func jsonString(_ value: String) -> String {
    var escaped = "\""
    for char in value {
        switch char {
        case "\"":
            escaped += "\\\""
        case "\\":
            escaped += "\\\\"
        case "\n":
            escaped += "\\n"
        case "\r":
            escaped += "\\r"
        case "\t":
            escaped += "\\t"
        default:
            escaped.append(char)
        }
    }
    escaped += "\""
    return escaped
}

