                if (j > 0) sb.append(" ");
                sb.append(String.format("%4d", row[j]));
            }
            System.out.println(sb.toString());
        }
    }

    static int determinant(int[][] M) {
        return M[0][0] * (M[1][1] * M[2][2] - M[1][2] * M[2][1])
             - M[0][1] * (M[1][0] * M[2][2] - M[1][2] * M[2][0])
             + M[0][2] * (M[1][0] * M[2][1] - M[1][1] * M[2][0]);
    }
}

