static char *read_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;
    size_t cap = 1024;
    size_t len = 0;
    char *buf = malloc(cap);
    if (!buf) { pclose(fp); return NULL; }
    char tmp[256];
    while (fgets(tmp, sizeof(tmp), fp)) {
        size_t tl = strlen(tmp);
        if (len + tl + 1 > cap) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) { free(buf); pclose(fp); return NULL; }
            buf = nb;
        }
        memcpy(buf + len, tmp, tl + 1);
        len += tl;
    }
    pclose(fp);
    buf[len] = 0;
    size_t end = strlen(buf);
    while (end > 0 && isspace((unsigned char)buf[end - 1])) {
        buf[--end] = 0;
    }
    return buf;
}

